    10	
    11	/// Loads server configuration and serves HTTP on port 6999.
    12	///
    13	/// # Errors
    14	/// Returns an error if configuration, runtime creation, or server startup fails.
    15	pub fn run_server() -> anyhow::Result<()> {
    16	    dotenvy::dotenv().ok();
    17	    let config = ServerConfig::from_env()?;
    18	
    19	    tokio::runtime::Runtime::new()?.block_on(async {
    20	        let listener = TcpListener::bind("0.0.0.0:6999").await?;
    21	        println!(
    22	            "Listening on http://localhost:{}",
    23	            listener.local_addr()?.port()
    24	        );
    25	        serve_exposed(&config, listener).await
    26	    })
    27	}
    28	
    29	/// Starts an `exposed` HTTP server
    30	///
    31	/// # Errors
    32	/// Returns an error if connecting to the database or serving HTTP fails.
    33	pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    34	    let db = ExposedDatabase::new(&config.connection_string).await?;
    35	    let service = EntitySearchService::new(db.clone(), db.clone());
    36	
    37	    let state = AppState {
    38	        entity_search_service: Arc::new(service),
    39	        entity_details_service: Arc::new(crate::domain::services::entity_details::Service::new(db)),
    40	    };
    41	    let router = routes().with_state(state);
    42	
    43	    axum::serve(listener, router).await?;
    44	
    45	    Ok(())
    46	}
