     7	#[derive(Error, Debug)]
     8	/// Errors communicated by the HTTP API
     9	pub enum ApiError {
    10	    #[error("internal server error")]
    11	    /// Private error, message should only be logged
    12	    InternalServerError,
    13	    /// Entity identity absent from the store.
    14	    #[error("entity not found")]
    15	    NotFound,
    16	    #[error("unable to process malformed request: {0}")]
    17	    /// Bad request from user
    18	    UnprocessibleEntity(String),
    19	}
    20	
    21	impl IntoResponse for ApiError {
    22	    fn into_response(self) -> Response {
    23	        let code = match self {
    24	            Self::NotFound => StatusCode::NOT_FOUND,
    25	            Self::InternalServerError => StatusCode::INTERNAL_SERVER_ERROR,
    26	            Self::UnprocessibleEntity(_) => StatusCode::UNPROCESSABLE_ENTITY,
    27	        };
    28	        (code, self.to_string()).into_response()
    29	    }
    30	}
