    28	pub async fn search_entities(
    29	    app: &Guard,
    30	    params: &EntitySearchRequest,
    31	) -> anyhow::Result<Vec<Value>> {
    32	    let client = reqwest::Client::new();
    33	
    34	    let port = app.port;
    35	
    36	    let (term, strictness, entries) = (params.term(), params.strictness(), params.max_entries());
    37	    let url = format!(
    38	        "http://127.0.0.1:{port}/search?term={term}&&strictness={strictness}&&max_entries={entries}"
    39	    );
    40	    let response = client.get(url).send().await?;
    41	
    42	    match response.status() {
    43	        StatusCode::OK => {
    44	            let bytes = response.bytes().await?;
    45	            let data: Value = serde_json::from_slice(&bytes)?;
    46	            let entities = data
    47	                .get("entities")
    48	                .and_then(|d| d.as_array())
    49	                .ok_or(anyhow::anyhow!("unparsable"))?
    50	                .to_vec();
    51	            Ok(entities)
    52	        }
    53	        StatusCode::INTERNAL_SERVER_ERROR => Err(anyhow::anyhow!("something unexpected happened")),
    54	        StatusCode::UNPROCESSABLE_ENTITY => Err(anyhow::anyhow!("bad url")),
